/**
 * 아르케 지형광 테마 데이터 — 유적. **광원이 지형이 아니라 하늘에 있다.**
 *
 * ## 이 행성에서 이 레이어의 주역은 발광이 아니라 부조다
 * 카르곤은 지형 저지의 용암이 유일한 광원이라 헤일로·심지가 화면을 지배했다. 아르케에는 그런
 * 열원이 없다. 여기서 경계에 붙는 밝음은 **저각 태양이 석재 모서리에 닿는 림**과 **이음매에
 * 자란 인광 이끼**뿐이고, 화면을 만드는 것은 그 반대편 — 접지 AO 띠·캐스트 섀도가 만드는
 * 석재 경계의 부조다. 그래서 `ao.alphaCap` 이 팔레트에서 가장 크고(0.7) `glow.alphaCap` 은
 * 카르곤의 절반 이하(0.26)다.
 *
 * ## 색은 채도로 갈리고 각도로 갈리지 않는다
 * 아르케의 자연색인 금갈색(≈38~41°)은 앰버 적탄(28.5°)과 옐로 적탄(50.9°) 사이 폭 2.4° 슬롯에
 * 끼여 **색상각으로는 전경과 분리할 수 없다.** 그래서 지형(타일셋)은 무채에 가깝게 내리고
 * (HSV 채도 0.04~0.09), 이 레이어의 팔레트만 넓은 골짜기(60.9°~184.2°)의 **차가운 끝**으로
 * 옮겼다 — 산화 청동·이끼의 녹청(159~168°)이다. 전경 신호색까지 거리는 최소 27° 이상이다.
 *
 * ⚠️ 안전 골짜기는 `computeSafeHueWindows(FOREGROUND_SIGNAL_COLORS, 10)` 의 **계산값**이다.
 * 여기 적힌 각도는 그 계산 결과를 설명하는 것이지 입력이 아니다.
 */

import type { TerrainLightTheme } from '../../contracts/terrainLight.js';

export const ARKE_TERRAIN_LIGHT: TerrainLightTheme = {
  themeId: 'arke',

  /**
   * 이음매 채널 색 4종 — 산화 청동과 인광 이끼. 전부 색상각 159~168° 로, 가장 가까운 전경
   * 신호색(아군 시안 194.2°)에서 27° 이상 떨어져 있다. 헤일로가 심지보다 어둡고 채도가 높다:
   * 이끼는 안쪽이 젖어 진하고 마른 표면이 옅게 바랜다.
   */
  channel: [
    { glow: 0x3d7266, core: 0x66b39c },
    { glow: 0x2f5a51, core: 0x5aa693 },
    { glow: 0x4f8f7e, core: 0x76c2ac },
    { glow: 0x35695d, core: 0x6fbfa6 },
  ],

  /**
   * 황혼 곱연산. 카르곤(0.38)보다 옅다 — 그쪽은 밝은 주황 지각 위의 주황 적을 눌러야 했지만
   * 아르케 지형은 이미 저채도·저휘도라 더 누르면 "재질 없는 회색"이 된다.
   * 틴트는 하늘 그림자 쪽으로 아주 살짝만 차갑다.
   */
  dusk: { alpha: 0.2, tint: 0x4c4f52 },

  /** 넓은 겹은 낮게. 이 행성에서 발광은 조연이다. */
  glow: { alphaCap: 0.26, width: 96, profileExp: 2.0 },
  /** 심지는 헤일로의 2배(계약 하한 1.8배) — 좁은 이음매만 또렷하게 살아난다. */
  core: { alphaCap: 0.52, width: 15, profileExp: 5.6 },

  /**
   * **이 레이어의 주역.** 폭 15 는 심지(15)와 같고 오프셋 14 로 심지 바깥에 앉는다.
   * 평정부 0.55 로 가장자리를 세워 "칠해진 얼룩"이 아니라 "석재가 지면에 닿는 자리"로 읽히게
   * 했다 — 유적은 덩어리가 땅에 얹혀 있어야 하고, 그 접지선이 없으면 벽화가 된다.
   */
  ao: {
    alphaCap: 0.7,
    tint: 0x4d4a45,
    width: 15,
    offset: 14,
    plateau: 0.55,
    falloffExp: 2.4,
    floor: 0.66,
  },

  /**
   * 캐스트 섀도. 오프셋 34 는 AO(14)의 2배를 넘겨 층이 갈린다. 저각 태양이라 그림자가 길고
   * (폭 56) 옅다 — 정오 태양이면 짧고 진했을 것이다.
   */
  shadow: { alphaCap: 0.48, tint: 0x5c5850, width: 56, offset: 34, minStrength: 0.14 },

  /**
   * 광원을 마주본 모서리. 이 행성에서 **유일하게 또렷하게 밝은 것**이며, 광원이 위에 있다는
   * 사실을 화면에서 진술하는 자리다. 색은 골짜기에서 가장 옅은 녹청 — 이끼가 마른 표면.
   * 오프셋 −16 은 |16| − 폭/2(5) = 11 > 심지 반폭(7.5) 이라 실제로 심지 밖이다.
   */
  rim: { alphaCap: 0.46, color: 0x8fd8c0, width: 10, widthFloor: 0.48, offset: -16, minStrength: 0.2 },

  /**
   * 세 번째 넓은 겹 — 무너진 천장 틈으로 드는 **빛기둥**. 카르곤 열기 기둥과 기하가 정확히
   * 뒤집혀 있다: 열은 아래에서 위로 올라가지만(`rise` 양수) 빛은 위에서 아래로 내린다
   * (`rise` 음수). 세로로 늘어나는 것(`stretch` 1.7)만 같다.
   */
  plume: {
    alphaCap: 0.16,
    color: 0x9ae0c8,
    width: 132,
    stretch: 1.7,
    rise: -78,
    profileExp: 2.2,
    minStrength: 0.64,
  },

  /**
   * 지역 필드 9타일(=576px). 1920×1080 화면에 "이끼가 번진 구역"이 서너 개 들어가는 크기다.
   *
   * `emberMin` 0.34 는 카르곤(0.28)보다 높다. 아르케는 헤일로 상한이 절반(0.26)이라, 계약이
   * 요구하는 실효 알파 하한 0.08 을 넘기려면 세기 하한이 그만큼 올라가야 하기 때문이다
   * (0.34 × 0.26 = 0.088). "완전히 꺼진 경계 없음"이 두 값의 **곱**으로만 성립한다는 것이
   * 카르곤 1·3차 실패가 남긴 교훈이고, 여기서는 그 곱이 하한을 거의 정확히 결정했다.
   */
  intensity: {
    regionTiles: 9,
    regionThreshold: 0.52,
    regionSpan: 0.16,
    emberMin: 0.34,
    emberMax: 0.58,
    emberModTiles: 3.2,
    emberRemapLo: 0.32,
    emberRemapHi: 0.68,
    widthBase: 0.5,
    widthGain: 0.45,
  },
};
